def validar_corte(ventas, inventario):
    if not ventas or not inventario:
        raise ValueError('El corte no contiene ventas o inventario.')
    if len({r['id'] for r in ventas}) != len(ventas):
        raise ValueError('Existen claves duplicadas en las lineas de venta.')
    if len({r['id'] for r in inventario}) != len(inventario):
        raise ValueError('Existen claves duplicadas en el inventario.')
    productos = {r['id'] for r in inventario}
    for r in ventas:
        if r['producto_id'] not in productos:
            raise ValueError('Venta sin producto en el inventario: ' + r['id'])
        if round(r['cantidad'] * r['unitario']) != r['venta']:
            raise ValueError('Importe de linea inconsistente: ' + r['id'])
        dt = datetime.fromisoformat(r['timestamp'])
        if dt.strftime('%Y-%m-%d') != r['fecha'] or dt.weekday() != r['dia_semana'] or dt.hour != r['hora']:
            raise ValueError('Campos temporales inconsistentes: ' + r['id'])
    return {'lineas': len(ventas), 'facturas': len({r['factura'] for r in ventas}),
            'productos': len(inventario), 'ingresos_cop': round(sum(r['venta'] for r in ventas))}


def leer_corte():
    datos = json.loads(zlib.decompress(base64.b64decode(CORTE_BASE64)))
    v, i, e, qa = (datos[k] for k in ('ventas', 'inventario', 'personal', 'qa'))
    validar_corte(v, i)
    qa['conciliacion_original'] = False
    qa['origen_datos'] = 'Corte normalizado del HTML suministrado'
    return v, i, e, qa

