def leer_csvs(folder: Path):
    datos = {}
    for name in NOMBRES:
        ruta = folder / (name + '.csv')
        if not ruta.exists():
            raise FileNotFoundError(f'No se encontró {ruta}. Extrae los CSV de la entrega antes de ejecutar.')
        with ruta.open('r', encoding='utf-8-sig', newline='') as f:
            datos[name] = list(csv.DictReader(f))
    return datos


def numero(v, defecto=0.0):
    try:
        x = float(v)
        return x if math.isfinite(x) else defecto
    except (ValueError, TypeError):
        return defecto


def entero(v):
    return int(numero(v))


def bloques(rows, campo):
    """IDs reiniciados, detectados por una nueva secuencia ordenada ascendente."""
    b = 1
    prev = None
    for row in rows:
        curr = entero(row[campo])
        if prev is not None and curr <= prev:
            b += 1
        row['_bloque'] = b
        prev = curr
    return b


def fecha_excel(v):
    """Excel fechas como número serial o texto ISO."""
    if isinstance(v, str) and re.fullmatch(r'\d{4}-\d{2}-\d{2}.*', v):
        return datetime.fromisoformat(v.replace('Z', '+00:00')).replace(tzinfo=None)
    return datetime(1899, 12, 30) + timedelta(days=numero(v))


def texto(v, default='Sin información'):
    return str(v).strip() if v is not None and str(v).strip() else default


def zona(direccion):
    partes = [p.strip() for p in (direccion or '').split(',')]
    return partes[-2] if len(partes) > 2 else 'Sin zona'


def familia(nombre):
    if not nombre or nombre.startswith('Producto sin nombre'):
        return 'Sin clasificar'
    return nombre.split()[0].capitalize()


def preparar_csv(folder: Path):
    t = leer_csvs(folder)
    for tb,col in [('Clientes','id_cliente'),('Empleados','id_empleado'),('Facturas','id_factura'),
                   ('Pedidos','id_pedido'),('Productos','id_producto')]:
        bloques(t[tb], col)
    clientes={(r['_bloque'],entero(r['id_cliente'])):r for r in t['Clientes']}
    empleados={(r['_bloque'],entero(r['id_empleado'])):r for r in t['Empleados']}
    productos={(r['_bloque'],entero(r['id_producto'])):r for r in t['Productos']}
    proveedores={entero(r['id_proveedor']):r for r in t['Proveedores']}
    pedidos=defaultdict(list)
    for o in t['Pedidos']:
        pedidos[(o['_bloque'],entero(o['id_factura']))].append(o)
    ventas=[]
    inconsistentes=[]
    for f in t['Facturas']:
        b=f['_bloque']; nf=entero(f['id_factura']); dt=fecha_excel(f['fecha'])
        cl=clientes.get((b,entero(f['id_cliente'])),{})
        em=empleados.get((b,entero(f['id_empleado'])),{})
        total_calculado=0
        filas=pedidos.get((b,nf),[])
        for pedido in filas:
            pi=entero(pedido['id_producto']); pr=productos.get((b,pi),{})
            prov=proveedores.get(entero(pr.get('id_proveedor',0)),{})
            cantidad=entero(pedido['cantidad']); pu=numero(pedido['precio_unitario'])
            importe=round(cantidad*pu)
            total_calculado+=importe
            prod_nombre=texto(pr.get('nombre'),f'Producto sin nombre #{pi} · B{b}')
            ventas.append({
                'id':f'B{b}-F{nf}-P{entero(pedido["id_pedido"])}',
                'factura':f'B{b}-{nf}','bloque':b,
                'fecha':dt.strftime('%Y-%m-%d'),'timestamp':dt.isoformat(timespec='minutes'),
                'mes':dt.strftime('%Y-%m'),'anio':dt.year,'mes_num':dt.month,
                'dia_semana':dt.weekday(),'hora':dt.hour,
                'cliente':f'B{b}-{entero(f["id_cliente"])}',
                'zona':zona(cl.get('direccion','')),
                'empleado':f'{texto(em.get("nombre"))} {texto(em.get("apellido"))} · B{b} / {entero(f["id_empleado"])}',
                'puesto':texto(em.get('puesto')),
                'producto_id':f'B{b}-{pi}',
                'producto':prod_nombre,'familia':familia(prod_nombre),
                'proveedor':texto(prov.get('nombre')),
                'cantidad':cantidad,'unitario':pu,'venta':importe,
                'salario_empleado':numero(em.get('salario'))
            })
        ft=round(numero(f['total']))
        if ft!=round(total_calculado):
            inconsistentes.append(f'B{b}-{nf}: factura {ft}, pedidos {total_calculado}')
    inventario=[]
    for p in t['Productos']:
        b=p['_bloque']; pi=entero(p['id_producto']); prov=proveedores.get(entero(p.get('id_proveedor',0)),{})
        n=texto(p.get('nombre'),f'Producto sin nombre #{pi} · B{b}')
        inventario.append({'id':f'B{b}-{pi}','bloque':b,'producto':n,'familia':familia(n),
                           'stock':entero(p.get('stock')),'precio':numero(p.get('precio')),
                           'proveedor':texto(prov.get('nombre'))})
    personal=[]
    for e in t['Empleados']:
        b=e['_bloque'];i=entero(e['id_empleado'])
        personal.append({'id':f'B{b}-{i}','bloque':b,
                         'nombre':f'{texto(e.get("nombre"))} {texto(e.get("apellido"))} · B{b} / {i}',
                         'puesto':texto(e.get('puesto')),'salario':numero(e.get('salario'))})
    if not ventas:
        raise ValueError('No se pudo construir ninguna venta.')
    verificaciones={'facturas':len(t['Facturas']),'pedidos':len(t['Pedidos']),
                    'clientes':len(t['Clientes']),'empleados':len(t['Empleados']),
                    'productos':len(t['Productos']),'proveedores':len(t['Proveedores']),
                    'facturas_inconsistentes':len(inconsistentes),
                    'detalles_inconsistencias':inconsistentes[:10],
                    'productos_sin_nombre':sum(not texto(x.get('nombre'),'') for x in t['Productos']),
                    'montos_ventas':int(round(sum(v['venta'] for v in ventas))),
                    'rango_desde':min(v['fecha'] for v in ventas),'rango_hasta':max(v['fecha'] for v in ventas)}
    # Al convertir None a str se debe revisar explícitamente: csv.DictReader usa '' para vacíos.
    verificaciones['productos_sin_nombre']=sum(not x.get('nombre','').strip() for x in t['Productos'])
    verificaciones['conciliacion_original'] = True
    return ventas,inventario,personal,verificaciones


def motor_sql(url):
    if not url: raise ValueError('Configura MITIENDA_DATABASE_URL o indica --db-url.')
    try:
        from sqlalchemy import create_engine
    except ImportError as exc:
        raise SystemExit('Falta SQLAlchemy; ejecuta pip install sqlalchemy') from exc
    opciones={'pool_pre_ping':True}
    if url.startswith('postgresql'):
        opciones.update(pool_size=2,max_overflow=0,
                        connect_args={'sslmode':'require','connect_timeout':8})
    return create_engine(url,**opciones)


def definicion_sql():
    from sqlalchemy import MetaData,Table,Column,String,Integer,Float,Numeric
    # Esquema privado: no queda expuesto por la API pública de Supabase.
    meta=MetaData(schema='mitienda_dw')
    v=Table('dw_mitienda_ventas',meta,
       Column('id',String(70),primary_key=True),Column('factura',String(40)),Column('bloque',Integer),
       Column('fecha',String(10)),Column('timestamp',String(32)),Column('mes',String(7)),Column('anio',Integer),
       Column('mes_num',Integer),Column('dia_semana',Integer),Column('hora',Integer),
       Column('cliente',String(30)),Column('zona',String(100)),Column('empleado',String(180)),
       Column('puesto',String(80)),Column('producto_id',String(30)),Column('producto',String(240)),
       Column('familia',String(70)),Column('proveedor',String(180)),
       Column('cantidad',Integer),Column('unitario',Numeric(18,2)),Column('venta',Numeric(18,2)))
    inv=Table('dw_mitienda_inventario',meta,
       Column('id',String(40),primary_key=True),Column('bloque',Integer),Column('producto',String(240)),
       Column('familia',String(70)),Column('stock',Integer),Column('precio',Numeric(18,2)),Column('proveedor',String(180)))
    emp=Table('dw_mitienda_personal',meta,
       Column('id',String(40),primary_key=True),Column('bloque',Integer),Column('nombre',String(180)),
       Column('puesto',String(80)))
    return meta,v,inv,emp


def subir_sql(url,ventas,inventario,personal):
    """Acción opt-in. Sustituye contenido de las tres tablas DW propias, no datos de otras tablas."""
    engine=motor_sql(url)
    meta,v,inv,emp=definicion_sql()
    with engine.begin() as con:
        con.exec_driver_sql('CREATE SCHEMA IF NOT EXISTS mitienda_dw')
    meta.create_all(engine)
    with engine.begin() as con:
        # Permite actualizar el corte respetando la relación producto–venta.
        for tb in (v,inv,emp):
            con.execute(tb.delete())
        for tb,records in ((inv,inventario),(emp,personal),(v,ventas)):
            columnas={c.name for c in tb.columns}
            con.execute(tb.insert(),[{k:x[k] for k in columnas if k in x} for x in records])
    engine.dispose()
    print(f'Conexión SQL verificada. DW cargado: {len(ventas)} líneas, {len(inventario)} productos, {len(personal)} empleados.')


def leer_sql(url):
    from sqlalchemy import select
    engine=motor_sql(url)
    _,v,inv,emp=definicion_sql()
    with engine.connect() as con:
        ventas=[dict(row) for row in con.execute(select(v)).mappings()]
        inventario=[dict(row) for row in con.execute(select(inv)).mappings()]
        personal=[dict(row) for row in con.execute(select(emp)).mappings()]
    engine.dispose()
    if not ventas: raise ValueError('La base SQL está vacía. Ejecuta primero --cargar-sql.')
    for records in (ventas, inventario, personal):
        for row in records:
            for key, value in row.items():
                if isinstance(value, Decimal): row[key] = float(value)
    validar_corte(ventas, inventario)
    vs={'facturas':len({v['factura'] for v in ventas}),'pedidos':len(ventas),
        'clientes':len({v['cliente'] for v in ventas}), 'empleados':len(personal),
        'productos':len(inventario),'proveedores':len({v['proveedor'] for v in ventas}),
        'conciliacion_original':len(ventas)==1600 and round(sum(v['venta'] for v in ventas))==203465700,
        'facturas_inconsistentes':0 if len(ventas)==1600 and round(sum(v['venta'] for v in ventas))==203465700 else None,
        'productos_sin_nombre':sum('Producto sin nombre' in x['producto'] for x in inventario),
        'montos_ventas':round(sum(v['venta'] for v in ventas)),
        'rango_desde':min(v['fecha'] for v in ventas),'rango_hasta':max(v['fecha'] for v in ventas),
        'origen_datos':'PostgreSQL · Supabase · esquema mitienda_dw'}
    return ventas,inventario,personal,vs


def imagen_seaborn(ventas,tipo):
    """Genera un SVG con Seaborn para los registros filtrados."""
    sns.set_theme(style='darkgrid',font_scale=.9)
    bg='#ffffff';fg='#23354b';grid='#d8e1e9'
    plt.rcParams.update({'figure.facecolor':bg,'savefig.facecolor':bg,'axes.facecolor':bg,
                         'axes.labelcolor':fg,'text.color':fg,'xtick.color':'#53677c',
                         'ytick.color':'#53677c','axes.edgecolor':grid,'grid.color':grid,
                         'font.family':'DejaVu Sans','svg.fonttype':'none'})
    fig,ax=plt.subplots(figsize=(9,3.8),dpi=110)
    if not ventas:
        ax.text(.5,.5,'Sin registros para los filtros seleccionados',ha='center',va='center',transform=ax.transAxes,color=fg)
        ax.set_xticks([]);ax.set_yticks([])
    elif tipo=='familias':
        ag=defaultdict(float)
        for x in ventas: ag[x['familia']]+=x['venta']
        best=sorted(ag,key=ag.get,reverse=True)[:9]
        sns.barplot(x=[ag[x]/1e6 for x in best][::-1],y=best[::-1],ax=ax,color='#244f79')
        ax.set_xlabel('Millones de pesos colombianos');ax.set_ylabel('')
        ax.set_title('Ingresos por familia · Seaborn',pad=13,color=fg)
    elif tipo=='calor':
        arr=np.zeros((7,24),dtype=int)
        for x in ventas:arr[int(x['dia_semana']),int(x['hora'])]+=1
        hours=list(range(24))
        sns.heatmap(arr,ax=ax,cmap='mako',linewidths=.6,linecolor='#edf2f6',
                    xticklabels=[f'{h:02d}' for h in hours],
                    yticklabels=['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'],
                    cbar_kws={'label':'Líneas de venta'})
        ax.set_xlabel('Hora');ax.set_ylabel('');ax.set_title('Actividad por día y hora · Seaborn',pad=13,color=fg)
    elif tipo=='dispersion':
        cnt=Counter(x['familia'] for x in ventas)
        fam=[x for x,_ in cnt.most_common(6)]
        sub=[x for x in ventas if x['familia'] in fam]
        if sub:
            sns.boxplot(x=[x['familia'] for x in sub],y=[x['venta']/1000 for x in sub],
                        order=fam,ax=ax,color='#6785ae',showfliers=True)
            ax.tick_params(axis='x',rotation=27)
        ax.set_xlabel('Familia');ax.set_ylabel('Importe de la línea (miles COP)')
        ax.set_title('Distribución del valor por familia · Seaborn',pad=13,color=fg)
    else:
        raise ValueError('tipo Seaborn desconocido')
    sns.despine(ax=ax)
    fig.tight_layout(pad=1.3)
    buf=BytesIO();fig.savefig(buf,format='svg',bbox_inches='tight');plt.close(fig)
    return 'data:image/svg+xml;base64,'+base64.b64encode(buf.getvalue()).decode('ascii')


