def construir_html(ventas,inventario,personal,qa,origen,output,dinamico=False):
    def safe_json(data):
        return json.dumps(data,ensure_ascii=False,separators=(',',':'),allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    js=JS.replace('__VENTAS__',safe_json(ventas)).replace('__INVENTARIO__',safe_json(inventario))\
          .replace('__PERSONAL__',safe_json(personal)).replace('__QA__',safe_json(qa))\
          .replace('__DINAMICO__','true' if dinamico else 'false').replace('__CHART_KINDS__',json.dumps(__import__('charts').KINDS))
    html=HTML.replace('__CSS__',CSS)
    html=re.sub(r'(<h3>[^<]+</h3>)(<div class="chart)',
                r'<div class="chart-heading">\1<span class="badge seaborn-badge">SEABORN · PYTHON</span></div>\2',html)
    html=html.replace('<span class="badge">SEABORN</span>','<span class="badge seaborn-badge">SEABORN · PYTHON</span>')
    html=html.replace('__JS__',js).replace('__ORIGEN__',origen)
    html=html.replace('__INTERVALO__',qa['rango_desde']+' a '+qa['rango_hasta'])
    original = qa.get('conciliacion_original', False)
    html=html.replace('__ESTADOINTEGRIDAD__', ('facturas originales conciliadas' if not qa.get('facturas_inconsistentes') else 'revisar facturas no conciliadas') if original else 'corte verificado; Excel original no disponible para conciliación')
    output.parent.mkdir(parents=True,exist_ok=True)
    output.write_text(html,encoding='utf-8')
    print('HTML generado:',output,'(',round(output.stat().st_size/1024/1024,2),'MB )')
    return html


def servidor(ventas,inventario,personal,qa,html,host,port):
    """Servidor incluido en Python: GET / y POST /api/seaborn sin Flask."""
    from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.path in ('/', '/index.html'):
                data=html.encode('utf-8'); content_type='text/html; charset=utf-8'
            elif self.path == '/health':
                data=json.dumps({'ready':True,'rows':len(ventas)}).encode('utf-8')
                content_type='application/json; charset=utf-8'
            elif self.path == '/Codigo_MiTienda.txt':
                data=Path(__file__).read_bytes();content_type='text/plain; charset=utf-8'
            else:
                self.send_error(404,'Recurso no encontrado');return
            self.send_response(200);self.send_header('Content-Type',content_type)
            if self.path == '/Codigo_MiTienda.txt':
                self.send_header('Content-Disposition','attachment; filename="Codigo_MiTienda.txt"')
            self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
        def do_POST(self):
            if self.path!='/api/seaborn':self.send_error(404);return
            try:
                size=int(self.headers.get('Content-Length','0'))
                if not 0<size<10000:raise ValueError('Tamaño de filtros no válido')
                body=json.loads(self.rfile.read(size))
                f=body.get('filters',{})
                if not isinstance(f,dict):raise ValueError('Filtros inválidos')
                sub=[r for r in ventas if (not f.get('start') or r['fecha']>=f['start'])
                    and (not f.get('end') or r['fecha']<=f['end'])
                    and (not f.get('block') or r['bloque']==int(f['block']))
                    and (not f.get('family') or r['familia']==f['family'])
                    and (not f.get('zone') or r['zona']==f['zone'])
                    and (not f.get('role') or r['puesto']==f['role'])
                    and (not f.get('q') or f['q'].lower() in r['producto'].lower() or f['q'].lower() in r['producto_id'].lower())]
                from charts import KINDS, render as render_chart
                block=int(f.get('block') or 0)
                selected_inventory=[r for r in inventario if (not block or r['bloque']==block)
                    and (not f.get('family') or r['familia']==f['family'])
                    and (not f.get('q') or f['q'].lower() in r['producto'].lower() or f['q'].lower() in r['id'].lower())]
                currency=f.get('currency','COP');trm=float(f.get('trm') or 4000)
                if currency not in ('COP','USD') or not 1<=trm<=100000:raise ValueError('Conversión inválida')
                with SEABORN_LOCK:
                    response={k:render_chart(k,sub,selected_inventory,currency,trm) for k in KINDS}
                data=json.dumps(response).encode('utf-8')
                self.send_response(200);self.send_header('Content-Type','application/json; charset=utf-8')
            except Exception as error:
                data=json.dumps({'error':str(error)}).encode('utf-8')
                self.send_response(400);self.send_header('Content-Type','application/json; charset=utf-8')
            self.send_header('Content-Length',str(len(data)));self.end_headers();self.wfile.write(data)
        def log_message(self,fmt,*args):
            if self.path!='/api/seaborn':super().log_message(fmt,*args)
    print(f'Servidor Python con Seaborn dinámico: http://{host}:{port}')
    ThreadingHTTPServer((host,port),Handler).serve_forever()


def main():
    parser=argparse.ArgumentParser(description='Dashboard MiTienda real · CSV/SQL + Seaborn')
    parser.add_argument('--carpeta',default=str(DATOS),help='Carpeta CSV de las 6 tablas originales')
    parser.add_argument('--salida',default=str(BASE/'Dashboard_MiTienda.html'))
    parser.add_argument('--fuente',choices=['incluido','csv','sql'],default='incluido')
    parser.add_argument('--db-url',default=os.environ.get('MITIENDA_DATABASE_URL',''),help='URL SQLAlchemy; evitar guardarla en repos públicos')
    parser.add_argument('--cargar-sql',action='store_true',help='Crea/refresca tablas dw_mitienda_* en la BD configurada')
    parser.add_argument('--servidor',action='store_true',help='Inicia servidor HTTP Python; recalcula los 21 gráficos Seaborn con cada filtro')
    parser.add_argument('--host',default='127.0.0.1');parser.add_argument('--puerto',type=int,default=8050)
    args=parser.parse_args()
    if args.fuente == 'sql':
        if args.cargar_sql:
            parser.error('Para cargar usa --fuente incluido o csv; después consulta con --fuente sql.')
        ventas, inv, emp, qa = leer_sql(args.db_url)
        origen = 'CONSULTA DIRECTA SQL / DW MITIENDA · CORTE DE EJECUCIÓN'
    elif args.fuente == 'csv':
        ventas, inv, emp, qa = preparar_csv(Path(args.carpeta))
        origen = 'MITIENDA / SEIS TABLAS CSV · CORTE DE EJECUCIÓN'
    else:
        ventas, inv, emp, qa = leer_corte()
        origen = 'MITIENDA / CORTE NORMALIZADO INCLUIDO EN LA ENTREGA'
    validar_corte(ventas, inv)
    if args.cargar_sql:
        subir_sql(args.db_url, ventas, inv, emp)
    print('Comprobación:',json.dumps(qa,ensure_ascii=False))
    html=construir_html(ventas,inv,emp,qa,origen,Path(args.salida),dinamico=args.servidor)
    if args.servidor:
        servidor(ventas,inv,emp,qa,html,args.host,args.puerto)


if __name__=='__main__':main()
